    /*
     * Add to the DirectReports
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Position
     */
    public Position addToDirectReports( UUID parentId, Position addTo ) {
	    LOGGER.info("handling AssignDirectReportsToPositionEvent - " );
	    
	    Position parentEntity = repository.findById(parentId).get();
	    Position child = registry.project( Position.class, addTo.getPositionId());
	    
	    parentEntity.getDirectReports().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the DirectReports
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Position
     */
	public Position removeFromDirectReports( UUID parentId, Position removeFrom ) {
	    LOGGER.info("handling RemoveDirectReportsFromPositionEvent " );
	
	    Position parentEntity = repository.findById(parentId).get();
	    Position child = registry.project( Position.class, removeFrom.getPositionId());
	    
	    parentEntity.getDirectReports().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}

